import { useState, useEffect } from 'react';
import { Note } from '../types';
import { updateNote } from '../lib/storage';

interface NoteEditorProps {
  note: Note;
}

export function NoteEditor({ note }: NoteEditorProps) {
  const [body, setBody] = useState(note.body);

  useEffect(() => {
    setBody(note.body);
  }, [note.id, note.body]);

  const handleChange = (value: string) => {
    setBody(value);
  };

  const handleBlur = () => {
    if (body !== note.body) {
      updateNote(note.id, { body });
    }
  };

  return (
    <div className="flex flex-col h-full p-6">
      <h2 className="text-xl font-semibold text-foreground mb-2">{note.title}</h2>
      <p className="text-xs text-muted-foreground mb-4">
        {new Date(note.createdAt).toLocaleString()}
      </p>
      <textarea
        value={body}
        onChange={(e) => handleChange(e.target.value)}
        onBlur={handleBlur}
        placeholder="Start writing..."
        className="flex-1 w-full resize-none bg-transparent text-foreground placeholder:text-muted-foreground text-sm leading-relaxed outline-none"
      />
    </div>
  );
}

