import { describe, it, expect, beforeEach } from 'vitest';
import { getNotes, saveNotes, addNote, updateNote, deleteNote, trimNotes } from './storage';

describe('storage', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  describe('getNotes', () => {
    it('returns empty array when no notes exist', () => {
      expect(getNotes()).toEqual([]);
    });

    it('returns parsed notes from localStorage', () => {
      const notes = [{ id: '1', title: 'Test', body: 'Body', createdAt: '2024-01-01' }];
      localStorage.setItem('notebox_notes', JSON.stringify(notes));
      expect(getNotes()).toEqual(notes);
    });
  });

  describe('saveNotes', () => {
    it('saves notes to localStorage', () => {
      const notes = [{ id: '1', title: 'Test', body: 'Body', createdAt: '2024-01-01' }];
      saveNotes(notes);
      expect(localStorage.getItem('notebox_notes')).toBe(JSON.stringify(notes));
    });
  });

  describe('addNote', () => {
    it('adds a new note with id and timestamp', () => {
      const note = addNote({ title: 'New Note', body: 'Content' });
      expect(note.id).toBeDefined();
      expect(note.title).toBe('New Note');
      expect(note.body).toBe('Content');
      expect(note.createdAt).toBeDefined();
    });

    it('adds new notes to the beginning of the list', () => {
      addNote({ title: 'First', body: '' });
      addNote({ title: 'Second', body: '' });
      const notes = getNotes();
      expect(notes[0].title).toBe('Second');
    });
  });

  describe('trimNotes', () => {
    it('returns all notes when under limit', () => {
      const notes = Array.from({ length: 30 }, (_, i) => ({
        id: String(i),
        title: `Note ${i}`,
        body: '',
        createdAt: new Date(i * 1000).toISOString(),
      }));
      expect(trimNotes(notes).length).toBe(30);
    });

    it('keeps newest notes when over limit', () => {
      const notes = Array.from({ length: 60 }, (_, i) => ({
        id: String(i),
        title: `Note ${i}`,
        body: '',
        createdAt: new Date(i * 1000).toISOString(),
      }));
      const trimmed = trimNotes(notes);
      expect(trimmed.length).toBe(50);
      expect(trimmed[0].title).toBe('Note 59'); // newest
      expect(trimmed[49].title).toBe('Note 10'); // oldest kept
    });
  });

  describe('updateNote', () => {
    it('updates an existing note', () => {
      const note = addNote({ title: 'Original', body: 'Body' });
      const updated = updateNote(note.id, { title: 'Updated' });
      expect(updated?.title).toBe('Updated');
    });

    it('returns null for non-existent note', () => {
      expect(updateNote('non-existent', { title: 'Test' })).toBeNull();
    });
  });

  describe('deleteNote', () => {
    it('removes a note from storage', () => {
      const note = addNote({ title: 'To Delete', body: '' });
      deleteNote(note.id);
      expect(getNotes().find((n) => n.id === note.id)).toBeUndefined();
    });
  });
});

