import { Note } from '../types';

const STORAGE_KEY = 'notebox_notes';
const MAX_NOTES = 50;

export function getNotes(): Note[] {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    if (!data) return [];
    return JSON.parse(data) as Note[];
  } catch {
    return [];
  }
}

export function saveNotes(notes: Note[]): void {
  const trimmed = trimNotes(notes);
  localStorage.setItem(STORAGE_KEY, JSON.stringify(trimmed));
}

export function addNote(note: Omit<Note, 'id' | 'createdAt'>): Note {
  const notes = getNotes();
  const newNote: Note = {
    ...note,
    id: crypto.randomUUID(),
    createdAt: new Date().toISOString(),
  };
  const updated = [newNote, ...notes];
  saveNotes(updated);
  return newNote;
}

export function updateNote(id: string, updates: Partial<Pick<Note, 'title' | 'body'>>): Note | null {
  const notes = getNotes();
  const index = notes.findIndex((n) => n.id === id);
  if (index === -1) return null;

  const updated = { ...notes[index], ...updates };
  notes[index] = updated;
  saveNotes(notes);
  return updated;
}

export function deleteNote(id: string): void {
  const notes = getNotes().filter((n) => n.id !== id);
  saveNotes(notes);
}

export function trimNotes(notes: Note[]): Note[] {
  if (notes.length <= MAX_NOTES) return notes;

  const sorted = [...notes].sort(
    (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
  );
  return sorted.slice(0, MAX_NOTES);
}

