import { useState, useEffect, useCallback } from 'react';
import { Note } from '../types';
import { getNotes, addNote } from '../lib/storage';
import { generateSeedNotes } from '../data/seed';
import { NoteList } from '../components/NoteList';
import { NoteEditor } from '../components/NoteEditor';
import { NoteDialog } from '../components/NoteDialog';
import { EmptyState } from '../components/EmptyState';
import { Plus, Trash2 } from 'lucide-react';

function sortNotesNewestFirst(notes: Note[]): Note[] {
  return [...notes].sort(
    (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
  );
}

export function NotesApp() {
  const [notes, setNotes] = useState<Note[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isDialogOpen, setIsDialogOpen] = useState(false);

  const loadNotes = useCallback(() => {
    let stored = getNotes();
    if (stored.length === 0) {
      const seeded = generateSeedNotes();
      stored = seeded;
      localStorage.setItem('notebox_notes', JSON.stringify(seeded));
    }
    setNotes(sortNotesNewestFirst(stored));
    if (stored.length > 0 && !selectedId) {
      setSelectedId(stored[0].id);
    }
  }, []);

  useEffect(() => {
    loadNotes();
  }, []);

  const handleCreateNote = (title: string, body: string) => {
    const newNote = addNote({ title, body });
    const updated = getNotes();
    setNotes(sortNotesNewestFirst(updated));
    setSelectedId(newNote.id);
  };

  const selectedNote = notes.find((n) => n.id === selectedId) ?? null;

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <header className="flex items-center justify-between px-6 py-4 border-b border-border">
        <h1 className="text-2xl font-bold text-foreground">Notebox</h1>
        <button
          onClick={() => setIsDialogOpen(true)}
          className="flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90 transition-colors text-sm font-medium"
        >
          <Plus className="h-4 w-4" />
          New Note
        </button>
      </header>

      {notes.length === 0 ? (
        <EmptyState />
      ) : (
        <div className="flex-1 flex overflow-hidden">
          <aside className="w-72 border-r border-border bg-card flex-shrink-0">
            <NoteList
              notes={notes}
              selectedId={selectedId}
              onSelect={setSelectedId}
            />
          </aside>
          <main className="flex-1 overflow-hidden">
            {selectedNote && <NoteEditor note={selectedNote} />}
          </main>
        </div>
      )}

      <NoteDialog
        isOpen={isDialogOpen}
        onClose={() => setIsDialogOpen(false)}
        onSubmit={handleCreateNote}
      />
    </div>
  );
}
